E = "https://www.etymonline.com/word/"

nodes = []

nodes.append({
 "id": 1, "lang": "Avestan", "words": "xerpta; hu-xerpta, hu-kehrpta",
 "verdict": "transcription_suspect",
 "derivation": "The Avestan words are real but the book's first transliteration is impossible. Bartholomae, AiW col. 1830, has j. hu-kǝhrp- Adj. 'wohlgestaltet' (of Haoma, Y.9.16) and j. hu-kǝrǝpta- Adj. 'schöngeformt' (of a woman's breasts, Yt.5.127), the latter a participle matching Skt. kḷptá- to kalpate 'is arranged, is fashioned'; the second element is kahrp-/kǝrǝf- f./n. 'the visible exterior of any being or thing, outward appearance, shape', also 'body' (BRT col. 454). Avestan has no initial /x/ here: the cluster is k-ǝ-h-r-p / k-ǝ-r-ǝ-p, so the book's 'xerpta' (with x) is a misprint or an idiosyncratic notation for kǝrǝpta-; the companion form 'hu-kehrpta' on the same line prints the k correctly, which shows the x is the error. On the derivation itself Nourai follows Pokorny exactly: IEW 926, under the root extension skel(e)-p- of (s)kel-1 'schneiden' (923-927), lists 'ai. kḷptá- ... = av. hu-kǝrǝpta- \"schöngeformt\", das jedoch auch zu kǝhrp- \"Gestalt\" (oben S. 620) gehören könnte' — i.e. Pokorny himself allows the attachment to the cutting/shaping root *(s)kel-p- but flags the alternative *kʷrep- 'body, form' (Latin corpus). Walde-Pokorny II 595 says the same. So the edge root→node is plausible, the form is not.",
 "derivation_fa": "واژه‌های اوستایی درست‌اند ولی نویسه‌گردانی نخست کتاب ناممکن است: بارتولومه در «فرهنگ ایرانی باستان» ستون ۱۸۳۰ صورت‌های hu-kǝhrp- «خوش‌اندام» و hu-kǝrǝpta- «زیبافرم» را آورده است؛ جزء دوم همان kahrp-/kǝrǝf- «پیکر، شکل بیرونی، تن» است. در اوستایی در این ریشه هیچ /خ/ آغازین نیست، پس «xerpta» خطای چاپی (یا نویسه‌گردانی شخصی) نورایی برای kǝrǝpta- است؛ همان سطر صورت درست «hu-kehrpta» را نیز چاپ کرده و همین نشان می‌دهد که x نادرست است. اما دربارهٔ خودِ پیوند، نورایی دقیقاً از پوکورنی پیروی کرده است: پوکورنی در ص ۹۲۶ ذیل گسترشِ ریشهٔ skel(e)-p- (از (s)kel- «بریدن») همین hu-kǝrǝpta- را می‌آورد و می‌افزاید که می‌تواند به kǝhrp- «پیکر» (ص ۶۲۰) هم وابسته باشد. پس «خطای چاپی کتاب» در صورت واژه، و پیوندِ ریشه‌شناختی «با احتیاط پذیرفتنی».",
 "error_in": "book",
 "book_prints": "xerpta : cut, shaped / hu-xerpta, hu-kehrpta : shaped like a boar, pig",
 "correct_form": "kǝrǝpta- (Av. hu-kǝrǝpta- 'beautifully formed', hu-kǝhrp- 'well-shaped')",
 "sources": ["https://en.wiktionary.org/wiki/Reconstruction:Proto-Indo-European/sek-"],
 "ref_check": [
   {"ref": "POK:926", "status": "supports", "note": "POK_03.txt line 2155, printed page header '926' at line 2151: 'vielleicht in ai. kálpate ... = av. hu-kǝrǝpta- ‚schöngeformt‘, das jedoch auch zu kǝhrp- ‚Gestalt‘ (oben S. 620) gehören könnte' — under 'Wurzelerweiterung skel(e)-p-' of (s)kel-1 'to cut'. Exactly Nourai's arrow, with Pokorny's own caveat."}
 ],
 "consulted": [
   {"src": "BRT", "where": "AiW s.vv. hu-kǝhrp-, hu-kǝrǝpta-, kahrp- (BRT.txt lines 30150, 30152, 9545)", "stance": "supports", "note": "'j. hu-kǝhrp- Adj. ‚wohlgestaltet‘: vaŋhuš haomō ... Y.9.16' ; 'j. hu-kǝrǝpta- Adj. ‚schöngeformt‘ ... Yt.5.127' ; 'j., g. kahrp-, kǝrǝf- f., n. ‚das sichtbare Äussere jedes Wesens und Dings, äussere Erscheinung, sichtbare Gestalt‘ ... insbes. ‚Leib, Körper‘'. No form with initial x-."},
   {"src": "WLD", "where": "Bd. II 595 s.v. (s)qel(e)-p- (WLD_Bd2_pages.txt line 39513)", "stance": "supports", "note": "'ai. kḷptá- ... == av. hu-kǝrǝpta- ‚schöngeformt‘ (Persson KZ. 33, 289f. ... s. auch u. *qrep- ‚Leib‘)' — same attachment and same caveat as Pokorny."},
   {"src": "AHD", "where": "Watkins, s.v. skel-1 'To cut' (AHD_watkins1985.txt)", "stance": "partial", "note": "Watkins gives the extended root *skelp- (SHELF, HALF, SCALPEL, SCULPTURE) but cites no Indo-Iranian material, so the Avestan word is simply absent from AHD."}
 ]})

